R=$RUN[refinement-fails-treat-r1]/fixture; cd $R/repo; for f in README.md src/tide_cache.py src/expiry_notice.py src/mooring.py src/dock_plan.py src/berth_fee.py src/sign.py; do echo "=== $f ($(wc -l <$f))"; cat -n $f; done
echo; for k in area adr spec lesson decision; do echo "=== kind:$k"; lore search --limit 50 "kind:$k" 2>&1 | grep -vE '^\s+[^/]*$' | sed "s#$R/vault/##"; done
lore areas 2>&1 | head; 
echo "=== kinds on disk"; ls $R/vault; 
for q in "kind:spec and tide" "days" "period" "keep" "policy" "30 days" "src/tide_cache.py"; do echo "=== $q"; lore search --limit 40 "$q" 2>&1 | grep -E '\[[a-z-]+/[a-z]+\]' | grep -v 'task/tide-cache-expire' | sed "s#$R/vault/##"; done
echo; lore record show spec/fixture-tide-expiry-spec; lore record show task/fixture-tide-expiry-spec-the-slice; lore record show task/fixture-tide-expiry-spec-a-finished-child

